const text = (name, max) => {
  const value = String(inputs[name] ?? "").trim();
  if (!value) throw new Error(`${name.replaceAll("_", " " )} is required.`);
  if (value.length > max) throw new Error(`${name.replaceAll("_", " " )} must be ${max} characters or fewer.`);
  return value;
};
const image = (name) => {
  const value = inputs[name];
  const hasUri = typeof value?.uri === "string" && value.uri.trim().length > 0;
  const hasData = typeof value?.data === "string" && value.data.length > 0;
  if (!value || typeof value !== "object" || value.type !== "image" || (!hasUri && !hasData)) throw new Error(`${name.replaceAll("_", " " )} is required.`);
  return value;
};
const productName = text("product_name", 120);
const campaignMessage = text("campaign_message", 600);
const audience = text("audience", 300);
const headline = text("headline", 120);
const cta = text("cta", 80);
const referenceRole = String(inputs.reference_role ?? "none").trim().toLowerCase();
const roles = ["none", "composition", "palette", "material", "lighting"];
if (!roles.includes(referenceRole)) throw new Error(`Reference role must be one of: ${roles.join(", " )}.`);
const productImage = image("product_image");
const images = [productImage];
let referenceImage = null;
if (referenceRole !== "none") {
  referenceImage = image("reference_image");
  images.push(referenceImage);
}
const referenceUse = String(inputs.reference_use ?? "").trim();
const referenceIgnore = String(inputs.reference_ignore ?? "").trim();
if (referenceUse.length > 300 || referenceIgnore.length > 300) throw new Error("Reference notes must be 300 characters or fewer.");
const brief = { schemaVersion: 1, productName, campaignMessage, audience, headline, cta, productImage, referenceImage, referenceRole, referenceUse, referenceIgnore };
const referenceInstruction = referenceRole === "none"
  ? "There is no optional visual reference. Use image 1 only."
  : `Image 2 has the single role '${referenceRole}'. Use: ${referenceUse || "the named role only"}. Ignore: ${referenceIgnore || "objects, branding, and product identity"}. Palette must not transfer objects. Lighting must not transfer the depicted product. Composition must not transfer branding.`;
const prompt = `Develop exactly three distinct written campaign directions for this captured brief.\n\nProduct: ${productName}\nCampaign message: ${campaignMessage}\nAudience: ${audience}\nExact headline: ${headline}\nExact CTA: ${cta}\n\nImage 1 is always the product identity reference and controls proportions, finish, lid, visible branding, and geometry. ${referenceInstruction}\n\nReturn JSON only, with this exact shape: {"directions":[{"id":"A","title":"...","setting":"...","composition":"...","lighting":"...","palette":"...","preservationInstructions":"..."},{"id":"B",...},{"id":"C",...}]}. Do not add campaign copy or change the approved headline or CTA.`;
await output("prompt", prompt);
await output("images", images);
await output("brief", JSON.stringify(brief));

const raw = String(inputs.response ?? "").trim();
let parsed;
try {
  parsed = JSON.parse(raw);
} catch {
  throw new Error("The direction model returned malformed JSON. Run the proposal again; no image was generated.");
}
let brief;
try { brief = JSON.parse(String(inputs.brief ?? "")); } catch { throw new Error("The captured brief is invalid. Return to the brief and propose again."); }
if (!parsed || !Array.isArray(parsed.directions) || parsed.directions.length !== 3) throw new Error("The direction response must contain exactly three directions.");
const requiredIds = ["A", "B", "C"];
const fields = ["title", "setting", "composition", "lighting", "palette", "preservationInstructions"];
const directions = parsed.directions.map((item, index) => {
  if (!item || typeof item !== "object") throw new Error(`Direction ${requiredIds[index]} is not an object.`);
  const id = String(item.id ?? "").trim();
  if (id !== requiredIds[index]) throw new Error("Directions must be ordered and identified as A, B, and C.");
  const clean = { id };
  for (const field of fields) {
    const value = String(item[field] ?? "").trim();
    if (!value) throw new Error(`Direction ${id} is missing ${field}.`);
    if (value.length > 600) throw new Error(`Direction ${id} ${field} is too long.`);
    clean[field] = value;
  }
  return clean;
});
if (new Set(directions.map((item) => item.id)).size !== 3) throw new Error("Direction IDs must be distinct.");
const markdown = directions.map((item) => `### ${item.id} — ${item.title}\n\n- Setting: ${item.setting}\n- Composition: ${item.composition}\n- Lighting: ${item.lighting}\n- Palette: ${item.palette}\n- Preserve: ${item.preservationInstructions}`).join("\n\n");
const plan = JSON.stringify({ schemaVersion: 1, brief, directions });
await output("directions", markdown);
await output("plan", plan);
await output("phase", "directions_ready");
